def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    urgent_opp_count = 0
    rich_opp_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        if opp.get('budget', 0) >= 200:
            rich_opp_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    my_urgent = (hp <= 2) or (no_water_days >= 1)
    my_risky = (hp <= 4)

    if my_urgent:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
        if budget < target:
            target = budget
        return float(max(0.0, min(budget, target)))

    if supply >= 23:
        base = DAILY_SALARY * 0.22
    elif supply >= 20:
        base = DAILY_SALARY * 0.34
    elif supply >= 17:
        base = DAILY_SALARY * 0.5
    else:
        base = DAILY_SALARY * 0.68

    if highest_prev >= 170:
        pressure_bid = highest_prev + 1.5
    elif highest_prev >= 140:
        pressure_bid = highest_prev + 2.0
    elif highest_prev >= 100:
        pressure_bid = max(avg_prev + 2.0, highest_prev * 0.92)
    elif highest_prev > 0:
        pressure_bid = max(base, highest_prev + 1.0)
    else:
        pressure_bid = base

    bid = base

    if supply <= 17:
        bid = max(bid, pressure_bid)
    elif supply <= 19 and (urgent_opp_count >= 2 or my_risky):
        bid = max(bid, min(pressure_bid, DAILY_SALARY * 0.9))
    elif my_risky:
        bid = max(bid, DAILY_SALARY * 0.62)
    else:
        if highest_prev >= 160 and hp >= 5 and no_water_days == 0:
            bid = min(bid, DAILY_SALARY * 0.3)
        elif highest_prev >= 120 and supply >= 20:
            bid = min(max(bid, DAILY_SALARY * 0.38), DAILY_SALARY * 0.48)
        elif rich_opp_count >= 2 and supply <= 18:
            bid = max(bid, DAILY_SALARY * 0.72)

    if day >= 8:
        if hp >= 5 and no_water_days == 0 and supply >= 20:
            bid = min(bid, DAILY_SALARY * 0.3)
        elif hp <= 4:
            bid = max(bid, DAILY_SALARY * 0.7)

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if days_left >= 2 and hp >= 4:
        reserve_floor = min(budget * 0.55, DAILY_SALARY * 2.2)
    max_spend = budget
    if budget > reserve_floor:
        max_spend = budget - reserve_floor + min(DAILY_SALARY * 0.35, reserve_floor)

    bid = min(bid, max_spend)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        # If alone, bid enough to secure water but avoid overpaying.
        cap = int(min(my_budget, DAILY_SALARY * 0.5))
        return max(0, cap)

    # Read yesterday's bids from previous_trace only.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Convert supply to an approximate number of water units we can cover if we win.
    # (We don't know exact allocation rule; use it only for bid scaling.)
    # Ensure integer indices if any list were used; here we avoid lists.
    supply_units = float(supply) / float(WATER_REQ)

    # Pressure-based bidding: if others were bidding near/above typical salary thresholds,
    # we raise our bid to avoid losing water.
    pressure_level = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure_level = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        pressure_level = 0.7
    elif highest_prev_bid > 0:
        pressure_level = 0.45

    # Our urgency increases with low hp and consecutive no-water days.
    urgency = 0.0
    if my_hp <= 2:
        urgency = 1.0
    elif my_hp <= 4:
        urgency = 0.7
    else:
        urgency = 0.4

    if my_no_water_days >= 2:
        urgency = max(urgency, 0.85)
    elif my_no_water_days >= 1:
        urgency = max(urgency, 0.6)

    # Base bid anchored to pressure and urgency.
    # Target slightly above highest_prev_bid when pressure is high; otherwise stay moderate.
    if pressure_level >= 1.0:
        target = highest_prev_bid + 2.0
    elif pressure_level >= 0.7:
        target = max(highest_prev_bid * 0.85, DAILY_SALARY * 0.55)
    else:
        target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.7)

    # Adjust for our urgency and supply scarcity.
    # If supply is near minimum, bidding should be higher.
    scarcity = 0.0
    if float(supply) <= float(MIN_SUPPLY) + 0.5:
        scarcity = 1.0
    elif float(supply) <= float((MIN_SUPPLY + MAX_SUPPLY) / 2.0):
        scarcity = 0.6
    else:
        scarcity = 0.3

    target = target * (0.85 + 0.35 * urgency + 0.2 * scarcity)

    # Safety caps: never exceed budget; also avoid extreme bids.
    # Use budget-aware cap to preserve survival.
    max_reasonable = min(my_budget, DAILY_SALARY * 1.2 + 0.5)
    bid = int(min(max_reasonable, max(0.0, target)))

    # If we are extremely low on hp, ensure we bid aggressively but still within budget.
    if my_hp <= 1:
        bid = int(min(my_budget, DAILY_SALARY * 1.05))

    return max(0, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    base_bid = DAILY_SALARY * 0.7

    competition_factor = 1 + (num_alive_opponents * 0.05)
    current_bid = base_bid * competition_factor

    available_water_units = int(day_context['supply'] // WATER_REQ)
    if available_water_units <= num_alive_opponents:
        current_bid += DAILY_SALARY * 0.15
    elif available_water_units > num_alive_opponents + 1:
        current_bid -= DAILY_SALARY * 0.1

    if my_status['hp'] <= 2:
        current_bid = max(current_bid, DAILY_SALARY * 0.95)
    elif my_status['hp'] == 3:
        current_bid = max(current_bid, DAILY_SALARY * 0.85)

    if day_context['day'] >= EPISODE_DAYS - 2 and my_status['budget'] > DAILY_SALARY * 2:
        current_bid += DAILY_SALARY * 0.1

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        if max_yesterday_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                current_bid = min(current_bid, DAILY_SALARY * 0.6)
            else:
                current_bid = max(current_bid, max_yesterday_bid + 5)
        elif max_yesterday_bid >= DAILY_SALARY * 0.6:
            current_bid = max(current_bid, max_yesterday_bid + 5)
        else:
            current_bid = max(current_bid, DAILY_SALARY * 0.7)

    final_bid = min(my_status['budget'], current_bid)
    final_bid = max(1, final_bid)

    return final_bid
